    # Build forward and reverse mappings to enforce bijection
    forward_map = {}
    reverse_set = set()

    for enc_char, orig_char in zip(encoded, original):
        if enc_char in forward_map:
            if forward_map[enc_char] != orig_char:
                return "Failed"  # Contradiction: same encoded char maps to multiple originals
        else:
            if orig_char in reverse_set:
                return "Failed"  # Contradiction: two encoded chars map to the same original
