            is_not = 'not' in tokens
            if not is_guilty:
                return False  # unexpected format
            if is_not:
                return name.upper() != scenario.upper()
            else:
                return name.upper() == scenario.upper()

        # If format not recognized, assume true (no violation)
        return True

    for speaker, stmts in statements.items():
        is_liar = speaker in liar_count
        for stmt in stmts:
            # Ignore statements about the day of the week
            stmt_lower = stmt.lower()
