def min_remaining_space(V, n, volumes):
    """Calculate the minimal leftover space in a box of capacity V
    after packing any subset of the first n items with given volumes."""
    # Ensure we only treat the first n volumes
    items = volumes[:n]
    # DP array: reachable[sum] = True if a subset sums to 'sum'
    reachable = [False] * (V + 1)
    reachable[0] = True
    for vol in items:
        if vol > V:
            # skip items that individually exceed the capacity
            continue
        # update reachable in reverse to avoid reuse in the same iteration
        for s in range(V, vol - 1, -1):
            if reachable[s - vol]:
                reachable[s] = True
    # Find the maximum achievable sum
    max_used = 0
    for s in range(V, -1, -1):
        if reachable[s]:
            max_used = s
            break
    return V - max_used

