            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # longest decreasing subsequence starting at each position
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # find maximum length of bitonic subsequence
    max_len = 0
    for i in range(n):
        length = inc[i] + dec[i] - 1
        if length > max_len:
            max_len = length

    # minimum removals = total students - longest bitonic subsequence length
    return n - max_len)

def hanoi_double_iterative(n: int) -> int:
    """Return the minimum number of moves for the double-disc Hanoi problem with n pairs of discs."""
    if n <= 0:
        return 0  # No discs, no moves needed
    moves = 2  # Base case for n == 1
    for _ in range(2, n + 1):
        moves = moves * 2 + 2
    return moves
